<?php
namespace Kitmage\Tutor\Entitlements\WooCommerce;
use Kitmage\Tutor\Entitlements\Repository\BatchRepository;
use Kitmage\Tutor\Entitlements\Repository\RedemptionRepository;
use Kitmage\Tutor\Entitlements\Service\TokenService;
final class MyAccount {const ENDPOINT='training-enrollments';public static function register(){add_action('init',static function(){add_rewrite_endpoint(self::ENDPOINT,EP_ROOT|EP_PAGES);});add_filter('woocommerce_account_menu_items',static function($items){$logout=$items['customer-logout']??null;unset($items['customer-logout']);$items[self::ENDPOINT]=__('Training Enrollments','tutor');if($logout)$items['customer-logout']=$logout;return $items;});add_action('woocommerce_account_'.self::ENDPOINT.'_endpoint',array(__CLASS__,'render'));}
	public static function render(){$batches=(new BatchRepository())->for_customer(get_current_user_id());echo '<h2>'.esc_html__('Training Enrollments','tutor').'</h2>';if(!$batches){echo '<p>'.esc_html__('No training entitlement purchases found.','tutor').'</p>';return;}foreach($batches as $b){$remaining=max(0,$b->entitlements_total-$b->entitlements_used-$b->entitlements_reserved);$token=TokenService::decrypt($b->token_cipher);echo '<section class="woocommerce-order-details"><h3>'.esc_html(get_the_title($b->course_id)?:sprintf(__('Course #%d','tutor'),$b->course_id)).'</h3><p>'.esc_html(sprintf(__('Order #%1$d · %2$d total · %3$d used · %4$d remaining','tutor'),$b->order_id,$b->entitlements_total,$b->entitlements_used,$remaining)).'</p><p>'.esc_html(sprintf(__('Status: %1$s · Expires: %2$s','tutor'),$b->status,get_date_from_gmt($b->expires_at,get_option('date_format')))).'</p>';if('active'===$b->status&&$remaining&&$token){$url=home_url('/training/redeem/'.$token.'/');echo '<p><input readonly value="'.esc_attr($url).'" style="width:80%"> <button type="button" onclick="navigator.clipboard.writeText(this.previousElementSibling.value)">'.esc_html__('Copy Link','tutor').'</button></p>';}$roster=(new RedemptionRepository())->roster($b->id);if($roster){echo '<table><thead><tr><th>'.esc_html__('Trainee','tutor').'</th><th>'.esc_html__('Redeemed','tutor').'</th></tr></thead><tbody>';foreach($roster as $r)echo '<tr><td>'.esc_html(trim($r->first_name_snapshot.' '.$r->last_name_snapshot)).'</td><td>'.esc_html(get_date_from_gmt($r->redeemed_at,get_option('date_format'))).'</td></tr>';echo '</tbody></table>';}echo '</section>';}}
}
